#pragma config(Motor,  port2,           right,         tmotorServoContinuousRotation, openLoop)
#pragma config(Motor,  port3,           left,          tmotorServoContinuousRotation, openLoop)
#pragma config(Motor,  port5,           hook,          tmotorServoStandard, openLoop)
#pragma config(Motor,  port6,           button,        tmotorServoStandard, openLoop)
#pragma config(Motor,  port8,           vertical,      tmotorServoContinuousRotation, openLoop)
#pragma config(Motor,  port9,           horizontal,    tmotorServoContinuousRotation, openLoop)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

void forward(int t)
{
	motor[port2] = 127;
	motor[port3] = 127;
	wait1Msec(t);
}
void turn_right(int t)
{
	motor[port2] = 127;
	motor[port3] = -127;
	wait1Msec(t);
}
void turn_left(int t)
{
	motor[port2] = -127;
	motor[port3] = 127;
	wait1Msec(t);
}
void push()
{
	motor[port2] = 0;
	motor[port3] = 0;
	motor[port6] = 127;
	wait1Msec(1000);
	motor[port6] = 127;
}
task main()
{
	motor[port6] = -127;
	forward(2000);
	turn_left(100);
	forward(2000);
	turn_right(100);
	forward(2000);
	turn_left(500);
	forward(500);
	turn_left(500);
	forward(1000);
	turn_left(500);
	forward(5000);
	push();
	turn_left(2000);
	forward(5000);
	turn_right(500);
	forward(1000);
	turn_right(500);
	forward(500);
	turn_right(500);
	forward(2000);
	turn_left(100);
	forward(2000);
	turn_right(100);
	forward(2000);
}
